    card.className = `buyer-guidance-card ${path.status === "Blocked" ? "is-risk" : ""}`;
    card.innerHTML = `
      <span>${String(index + 1).padStart(2, "0")}</span>
      <div>
        <strong>${escapeHtml(path.title)}</strong>
        <p>${escapeHtml(path.detail)}</p>
      </div>
      <b>${escapeHtml(path.status)}</b>
    `;
